  skins=function(){const entries=ssRegistry.filter(s=>(state.ssDebug||!s.debugOnly)&&(state.ssFilter!=='animated'||s.animated)&&(state.ssFilter!=='static'||!s.animated));return `${subhead(ssTexts.headerSkinTitle)}<div class="ss-filters">${[['all',ssTexts.headerSkinTabAll],['animated',ssTexts.headerSkinTabAnimated],['static',ssTexts.headerSkinTabStatic]].map(([id,title])=>btn('ss-filter:'+id,esc(title),title,'',`aria-pressed="${state.ssFilter===id}"`)).join('')}</div><div class="ss-scroll"><p class="ss-subtitle">${esc(ssTexts.headerSkinSubtitle)}</p>${ssGroups.map(g=>{const group=entries.filter(s=>s.group===g);return group.length?`<section class="ss-group" data-skin-group="${g}"><h3>${esc(ssTexts['headerSkinGroup'+(g==='basic'?'Basic':g[0].toUpperCase()+g.slice(1))])}</h3><div class="ss-grid">${group.map(s=>ssCard(s)).join('')}</div></section>`:''}).join('')}</div>`;};
  const ssFlows=[['skins-animated','皮肤 · 动态与固定配色','animated',false],['skins-static','皮肤 · 静态系列','static',false],['skins-debug','皮肤 · 调试SVG示例','all',true]];
