  const ssPreviousRender=fRender;fRender=function(key){const item=ssFlows.find(s=>s[0]===key);if(item){state.ssFilter=item[2];state.ssDebug=item[3];return skins();}return ssPreviousRender(key);};
  const ssPicker=document.createElement('optgroup');ssPicker.label='皮肤 · 筛选与调试';for(const[key,title]of ssFlows)ssPicker.appendChild(new Option(title,'flow-'+key));picker.appendChild(ssPicker);
  root.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el?.dataset.action.startsWith('ss-'))return;event.preventDefault();event.stopImmediatePropagation();const[action,id]=el.dataset.action.split(':');if(action==='ss-filter'){state.ssFilter=id;state.page='skins';render();}else if(action==='ss-select'){const next=skinOptions.find(s=>s.id===id);if(next.bound){if(!ssRegistry.find(s=>s.id===settings.skin)?.fixed)settings.userAccent=settings.accent;settings.accent=next.bound;}else if(ssRegistry.find(s=>s.id===settings.skin)?.fixed){settings.accent=settings.userAccent||'#f8c91c';}settings.skin=id;persist();render();}},true);
